def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # For every 1, fill the immediate continuation cells on each cardinal ray to another 1,
    # stopping at first non-8. Color the intervening cells as 2.
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=1: continue
        for dr,dc in ((0,1),(1,0)):
          rr,cc=r+dr,c+dc
          while rr<h and cc<w and grid[rr][cc]==8: rr+=dr; cc+=dc
          if rr<h and cc<w and grid[rr][cc]==1:
            rr,cc=r+dr,c+dc
            while (rr,cc)!=(rr,cc): pass
    # bridge only when direct line endpoints are separated by 8s
    for r in range(h):
      cs=[c for c in range(w) if grid[r][c]==1]
      for a,b in zip(cs,cs[1:]):
        if all(grid[r][c]==8 for c in range(a+1,b)):
          for c in range(a+1,b): out[r][c]=2
    for c in range(w):
      rs=[r for r in range(h) if grid[r][c]==1]
      for a,b in zip(rs,rs[1:]):
        if all(grid[r][c]==8 for r in range(a+1,b)):
          for r in range(a+1,b): out[r][c]=2
    return out
