    # marking the bridge in color 2. Bridges are allowed across gaps only.
    for r in range(h):
        pts=[c for c,v in enumerate(grid[r]) if v!=bg]
        for a,b in zip(pts,pts[1:]):
            if grid[r][a]==grid[r][b]:
