def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # For each line, bridge consecutive occurrences of the same non-background color.
    # The background is the most frequent color in these ARC grids.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] != bg]
        for a, b in zip(marks, marks[1:]):
            if grid[r][a] == grid[r][b]:
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != bg]
        for a, b in zip(marks, marks[1:]):
            if grid[a][c] == grid[b][c]:
                for r in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
