def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Based on the demonstrations, fill background cells between consecutive
    # non-background marks on every row and column with 2.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] != background]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != background]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
